-- =============================================================================
-- PLANTOPOLIS — Script de Inicialización PostgreSQL (Esquema + Datos Semilla)
-- =============================================================================
-- Define las 24 tablas del modelo de dominio de Plantopolis, sus restricciones
-- de integridad referencial, funciones de compatibilidad para respaldos y datos
-- semilla ficticios seguros para repositorios públicos.
-- =============================================================================

SET client_encoding = 'UTF8';

-- Conversión implícita de integer (1/0) a boolean (true/false) para permitir
-- restaurar sin errores copias de seguridad históricas generadas en Oracle.
CREATE OR REPLACE FUNCTION public.int_to_bool(val integer) RETURNS boolean AS $$
    SELECT val <> 0;
$$ LANGUAGE sql IMMUTABLE STRICT;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_cast
        WHERE castsource = 'integer'::regtype AND casttarget = 'boolean'::regtype
    ) THEN
        CREATE CAST (integer AS boolean) WITH FUNCTION public.int_to_bool(integer) AS IMPLICIT;
    END IF;
END
$$;

-- ── 1. TABLAS CATÁLOGO Y MAESTRAS ────────────────────────────────────────────

CREATE TABLE rol (
    id_rol BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_rol VARCHAR(50) NOT NULL CONSTRAINT uq_rol_nombre UNIQUE
);

CREATE TABLE estadopedido (
    id_estado_pedido BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion_estado VARCHAR(80) NOT NULL CONSTRAINT uq_estado_pedido UNIQUE
);

CREATE TABLE estadocarrito (
    id_estado_carrito BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion VARCHAR(50) NOT NULL CONSTRAINT uq_estado_carrito UNIQUE
);

CREATE TABLE metodopago (
    id_metodo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_metodo VARCHAR(80) NOT NULL CONSTRAINT uq_metodo_pago UNIQUE
);

CREATE TABLE estadopago (
    id_estado_pago BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    descripcion_estado_pago VARCHAR(50) NOT NULL CONSTRAINT uq_estado_pago UNIQUE
);

CREATE TABLE causamerma (
    id_causa BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_causa VARCHAR(80) NOT NULL CONSTRAINT uq_causa_nombre UNIQUE,
    activo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE categoria (
    id_categoria BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_categoria VARCHAR(100) NOT NULL CONSTRAINT uq_categoria_nombre UNIQUE,
    descripcion TEXT
);

CREATE TABLE tipoproducto (
    id_tipo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_tipo VARCHAR(80) NOT NULL CONSTRAINT uq_tipoproducto_nombre UNIQUE
);

CREATE TABLE zona (
    id_zona BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL CONSTRAINT uq_zona_nombre UNIQUE,
    capacidad_maxima INTEGER NOT NULL,
    tipo_condicion VARCHAR(50) NOT NULL,
    exposicion_solar VARCHAR(50) NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE proveedor (
    id_proveedor BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre VARCHAR(150) NOT NULL,
    contacto VARCHAR(100),
    telefono VARCHAR(20),
    correo VARCHAR(150),
    tipo_insumo VARCHAR(100) NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ── 2. TABLAS PRINCIPALES DE NEGOCIO ─────────────────────────────────────────

CREATE TABLE usuario (
    id_usuario BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_rol BIGINT NOT NULL CONSTRAINT fk_usuario_rol REFERENCES rol(id_rol),
    nombre_completo VARCHAR(150) NOT NULL,
    correo VARCHAR(150) NOT NULL CONSTRAINT uq_usuario_correo UNIQUE,
    contrasena_hash VARCHAR(255) NOT NULL,
    telefono VARCHAR(20),
    direccion VARCHAR(255),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    ultimo_token VARCHAR(500),
    fecha_registro TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE producto (
    id_producto BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_categoria BIGINT NOT NULL CONSTRAINT fk_producto_categoria REFERENCES categoria(id_categoria),
    id_tipo BIGINT NOT NULL CONSTRAINT fk_producto_tipo REFERENCES tipoproducto(id_tipo),
    nombre_producto VARCHAR(150) NOT NULL,
    descripcion TEXT,
    precio NUMERIC(10, 2) NOT NULL,
    porcentaje_iva NUMERIC(5, 2) NOT NULL DEFAULT 19.00,
    stock INTEGER NOT NULL DEFAULT 0,
    stock_minimo_alerta INTEGER NOT NULL DEFAULT 5,
    imagen_url VARCHAR(300),
    cuidados TEXT,
    luz VARCHAR(100),
    riego VARCHAR(100),
    tamanio_estimado VARCHAR(100),
    activo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE carrito (
    id_carrito BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario BIGINT NOT NULL CONSTRAINT fk_carrito_usuario REFERENCES usuario(id_usuario),
    id_estado_carrito BIGINT NOT NULL CONSTRAINT fk_carrito_estado REFERENCES estadocarrito(id_estado_carrito),
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE pedido (
    id_pedido BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_usuario BIGINT NOT NULL CONSTRAINT fk_pedido_usuario REFERENCES usuario(id_usuario),
    id_estado_pedido BIGINT NOT NULL CONSTRAINT fk_pedido_estado REFERENCES estadopedido(id_estado_pedido),
    numero_pedido VARCHAR(30) NOT NULL CONSTRAINT uq_pedido_numero UNIQUE,
    subtotal NUMERIC(10, 2) NOT NULL,
    impuestos NUMERIC(10, 2) NOT NULL,
    total NUMERIC(10, 2) NOT NULL,
    direccion_envio VARCHAR(255) NOT NULL,
    fecha_pedido TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE loteproduccion (
    id_lote BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo_lote VARCHAR(50) NOT NULL CONSTRAINT uq_lote_codigo UNIQUE,
    especie VARCHAR(100) NOT NULL,
    cantidad_inicial INTEGER NOT NULL,
    cantidad_actual INTEGER NOT NULL,
    cantidad_merma INTEGER NOT NULL DEFAULT 0,
    fecha_siembra DATE NOT NULL,
    estado_lote VARCHAR(40) NOT NULL CONSTRAINT ck_lote_estado CHECK (estado_lote IN ('GERMINANDO', 'CRECIENDO', 'LISTO_PARA_VENTA', 'DESCARTADO', 'EN_TIENDA')),
    id_zona BIGINT NOT NULL CONSTRAINT fk_lote_zona REFERENCES zona(id_zona),
    id_proveedor BIGINT CONSTRAINT fk_lote_proveedor REFERENCES proveedor(id_proveedor),
    id_producto BIGINT CONSTRAINT fk_lote_producto REFERENCES producto(id_producto),
    es_vinculado BOOLEAN NOT NULL DEFAULT FALSE,
    fecha_vinculacion TIMESTAMP,
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ── 3. TABLAS DEPENDIENTES Y AUDITORÍA OPERATIVA ─────────────────────────────

CREATE TABLE carritoitem (
    id_item BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_carrito BIGINT NOT NULL CONSTRAINT fk_item_carrito REFERENCES carrito(id_carrito),
    id_producto BIGINT NOT NULL CONSTRAINT fk_item_producto REFERENCES producto(id_producto),
    cantidad INTEGER NOT NULL
);

CREATE TABLE detallepedido (
    id_detalle BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pedido BIGINT NOT NULL CONSTRAINT fk_dp_pedido REFERENCES pedido(id_pedido),
    id_producto BIGINT NOT NULL CONSTRAINT fk_dp_producto REFERENCES producto(id_producto),
    cantidad INTEGER NOT NULL,
    precio_unitario NUMERIC(10, 2) NOT NULL,
    subtotal NUMERIC(10, 2) NOT NULL
);

CREATE TABLE pago (
    id_pago BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_pedido BIGINT NOT NULL CONSTRAINT uq_pago_pedido UNIQUE CONSTRAINT fk_pago_pedido REFERENCES pedido(id_pedido),
    id_metodo BIGINT NOT NULL CONSTRAINT fk_pago_metodo REFERENCES metodopago(id_metodo),
    id_estado_pago BIGINT NOT NULL CONSTRAINT fk_pago_estado REFERENCES estadopago(id_estado_pago),
    monto NUMERIC(10, 2) NOT NULL,
    pasarela_transaccion_id VARCHAR(100),
    factura_pdf_url VARCHAR(300),
    fecha_pago TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE historialestadolote (
    id_historial_lote BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_lote BIGINT NOT NULL CONSTRAINT fk_hlt_lote REFERENCES loteproduccion(id_lote),
    id_usuario BIGINT NOT NULL CONSTRAINT fk_hlt_usuario REFERENCES usuario(id_usuario),
    estado_anterior VARCHAR(40) NOT NULL CONSTRAINT ck_hist_estado_ant CHECK (estado_anterior IN ('NINGUNO', 'GERMINANDO', 'CRECIENDO', 'LISTO_PARA_VENTA', 'DESCARTADO', 'EN_TIENDA')),
    estado_nuevo VARCHAR(40) NOT NULL CONSTRAINT ck_hist_estado_nuevo CHECK (estado_nuevo IN ('GERMINANDO', 'CRECIENDO', 'LISTO_PARA_VENTA', 'DESCARTADO', 'EN_TIENDA')),
    observaciones TEXT,
    fecha_cambio TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE merma (
    id_merma BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_lote BIGINT NOT NULL CONSTRAINT fk_merma_lote REFERENCES loteproduccion(id_lote),
    id_causa BIGINT NOT NULL CONSTRAINT fk_merma_causa REFERENCES causamerma(id_causa),
    id_usuario BIGINT NOT NULL CONSTRAINT fk_merma_usuario REFERENCES usuario(id_usuario),
    cantidad_perdida INTEGER NOT NULL,
    fecha_merma DATE NOT NULL,
    observaciones TEXT,
    fecha_registro TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE tarearecurrente (
    id_tarea_recurrente BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_tarea VARCHAR(50) NOT NULL,
    prioridad VARCHAR(20) NOT NULL,
    frecuencia_dias INTEGER NOT NULL,
    id_zona BIGINT CONSTRAINT fk_tr_zona REFERENCES zona(id_zona),
    id_lote BIGINT CONSTRAINT fk_tr_lote REFERENCES loteproduccion(id_lote),
    id_trabajador_asignado BIGINT CONSTRAINT fk_tr_trabajador REFERENCES usuario(id_usuario),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    fecha_proxima_ejecucion DATE NOT NULL,
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    descripcion VARCHAR(500)
);

CREATE TABLE tarea (
    id_tarea BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tarea_recurrente BIGINT CONSTRAINT fk_ta_recurrente REFERENCES tarearecurrente(id_tarea_recurrente),
    tipo_tarea VARCHAR(50) NOT NULL,
    prioridad VARCHAR(20) NOT NULL,
    estado_tarea VARCHAR(40) NOT NULL,
    id_zona BIGINT CONSTRAINT fk_ta_zona REFERENCES zona(id_zona),
    id_lote BIGINT CONSTRAINT fk_ta_lote REFERENCES loteproduccion(id_lote),
    id_trabajador_asignado BIGINT CONSTRAINT fk_ta_trabajador REFERENCES usuario(id_usuario),
    fecha_limite DATE NOT NULL,
    alerta_vencida_enviada BOOLEAN NOT NULL DEFAULT FALSE,
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_completada TIMESTAMP,
    descripcion VARCHAR(500)
);

CREATE TABLE historialtarea (
    id_historial_tarea BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tarea BIGINT NOT NULL CONSTRAINT fk_ht_tarea REFERENCES tarea(id_tarea),
    id_usuario BIGINT NOT NULL CONSTRAINT fk_ht_usuario REFERENCES usuario(id_usuario),
    tipo_cambio VARCHAR(30) NOT NULL,
    estado_anterior VARCHAR(40),
    estado_nuevo VARCHAR(40),
    id_trabajador_anterior BIGINT CONSTRAINT fk_ht_trab_ant REFERENCES usuario(id_usuario),
    id_trabajador_nuevo BIGINT CONSTRAINT fk_ht_trab_nue REFERENCES usuario(id_usuario),
    fecha_cambio TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE comentariotarea (
    id_comentario BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_tarea BIGINT NOT NULL CONSTRAINT fk_cta_tarea REFERENCES tarea(id_tarea),
    id_usuario BIGINT NOT NULL CONSTRAINT fk_cta_usuario REFERENCES usuario(id_usuario),
    comentario TEXT NOT NULL,
    fecha_creacion TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

