INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (1, 1, 1, 'Monstera Deliciosa', 'La icónica costilla de Adán.', 45000, 19, 145, 10, 'https://images.unsplash.com/photo-1614594975525-e45190c55d0b?w=500', 'Limpiar hojas con paño húmedo.', 'Luz indirecta', 'Moderado', '60 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (2, 3, 1, 'Aloe Vera', 'Planta medicinal y decorativa.', 15000, 19, 99, 20, 'https://images.unsplash.com/photo-1596547609652-9cf5d8d76921?w=500', 'Evitar encharcamiento.', 'Sol directo', 'Escaso', '30 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (3, 1, 1, 'Sansevieria Trifasciata', 'Conocida como Lengua de Suegra, purifica el aire de tu hogar.', 28000, 19, 75, 15, 'https://images.unsplash.com/photo-1593482892290-f54927ae1bf6?w=500', 'Prácticamente indestructible. Abonar en primavera.', 'Soporta poca luz', 'Escaso (1 vez cada 3 semanas)', '40 cm - 80 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (4, 2, 1, 'Calatea Zebrina', 'Planta de follaje rayado verde y púrpura.', 10000, 19, 7, 5, 'https://images.unsplash.com/photo-1545241047-6083a3684587?w=500', 'Mantener sustrato húmedo sin encharcar.', 'Luz indirecta', 'Cada 5 dias', '50cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (5, 1, 1, 'Ficus Lyrata', 'Elegante planta de interior con grandes hojas en forma de violín.', 85000, 19, 30, 5, 'https://images.unsplash.com/photo-1545241047-6083a3684587?w=500', 'Rotar la maceta periódicamente para evitar crecimiento torcido.', 'Luz indirecta abundante', 'Moderado (sin encharcar)', '100 cm - 150 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (6, 3, 1, 'Árbol de Jade (Crassula Ovata)', 'Suculenta leñosa asociada a la abundancia y buena suerte.', 25000, 19, 80, 15, 'https://images.unsplash.com/photo-1509423350716-97f9360b4e09?w=500', 'Requiere buen drenaje. Propensa a cochinilla si hay exceso de agua.', 'Sol directo parcial', 'Escaso', '30 cm - 50 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (7, 2, 2, 'Limonero Enano', 'Ideal para patios, produce limones durante casi todo el año.', 120000, 19, 20, 5, 'https://images.unsplash.com/photo-1582281298055-e25b84a30b0b?w=500', 'Abono rico en potasio en floración. Vigilar minador de hojas.', 'Sol directo (mínimo 6 hrs)', 'Frecuente en verano', '120 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (8, 2, 2, 'Naranjo Washington Navel', 'Árbol frutal de exterior que da naranjas dulces y sin semillas.', 135000, 19, 15, 3, 'https://images.unsplash.com/photo-1547514701-42782101795e?w=500', 'Proteger de heladas intensas en invierno.', 'Sol directo', 'Frecuente', '150 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (9, 2, 3, 'Lavanda Inglesa', 'Arbusto aromático famoso por sus flores moradas y aroma relajante.', 18000, 19, 90, 20, 'https://images.unsplash.com/photo-1528183429752-a97d0bf99b5a?w=500', 'Podar después de la floración para mantener forma compacta.', 'Sol directo', 'Bajo (muy resistente a sequías)', '40 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (10, 2, 3, 'Romero', 'Arbusto perenne aromático y culinario indispensable en la cocina.', 12000, 19, 120, 25, 'https://images.unsplash.com/photo-1515542622106-78bda8ba0e5b?w=500', 'Excelente en suelos pobres. No encharcar.', 'Sol directo pleno', 'Escaso', '50 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (11, 2, 3, 'Menta Piperita', 'Perfecta para infusiones y cócteles, de crecimiento invasivo.', 10000, 19, 150, 30, 'https://images.unsplash.com/photo-1628556270448-4d4e4148e1b1?w=500', 'Plantar preferiblemente en maceta individual.', 'Semisombra o sol parcial', 'Frecuente (mantener húmedo)', '25 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (12, 1, 3, 'Albahaca Genovesa', 'Hoja ancha aromática, clásica para el pesto y la cocina italiana.', 9000, 19, 80, 15, 'https://images.unsplash.com/photo-1618375569909-3c8616cf7733?w=500', 'Cortar las flores apenas salgan para extender la vida de la planta.', 'Luz directa moderada', 'Moderado a frecuente', '30 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (13, 3, 1, 'Echeveria Elegans', 'Hermosa suculenta en forma de roseta, perfecta para arreglos.', 14000, 19, 60, 10, 'https://images.unsplash.com/photo-1509423350716-97f9360b4e09?w=500', 'Regar solo en la base, no mojar las hojas.', 'Sol directo suave', 'Muy escaso', '15 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (14, 3, 1, 'Cactus San Pedro', 'Cactus de crecimiento rápido, alto y majestuoso.', 40000, 19, 235, 8, 'https://images.unsplash.com/photo-1509423350716-97f9360b4e09?w=500', 'Usar sustrato para cactus y regar esporádicamente.', 'Sol directo', 'Escaso', '80 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (15, 1, 1, 'Zamioculca Zamiifolia (Planta ZZ)', 'La planta ideal para oficinas: elegante y super resistente.', 55000, 19, 45, 10, 'https://images.unsplash.com/photo-1632207691143-643e2a9a9361?w=500', 'Almacena agua en sus raíces, el exceso de riego es fatal.', 'Se adapta a poca luz', 'Muy escaso (cada 3-4 semanas)', '60 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (16, 1, 1, 'Calathea Medallion', 'Impresionante follaje con patrones decorativos exóticos.', 32000, 19, 50, 12, 'https://images.unsplash.com/photo-1545241047-6083a3684587?w=500', 'Sensible al agua del grifo, usar agua filtrada o reposada.', 'Luz indirecta o semisombra', 'Moderado (mantener humedad)', '45 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (17, 2, 1, 'Buganvilla Trepadora', 'Explosión de color magenta que decora muros y rejas en verano.', 38000, 19, 35, 8, 'https://images.unsplash.com/photo-1545241047-6083a3684587?w=500', 'Soporta sequía. Florece más con riegos espaciados.', 'Sol directo intenso', 'Moderado a escaso', 'Trepador hasta 3m', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (18, 2, 1, 'Ave del Paraíso (Strelitzia)', 'Flores exóticas que asemejan la cabeza de un pájaro tropical.', 65000, 19, 25, 5, 'https://images.unsplash.com/photo-1545241047-6083a3684587?w=500', 'Abonar rico en fósforo para asegurar buena floración.', 'Sol directo o semisombra brillante', 'Moderado', '100 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (19, 2, 1, 'Hortensia Macrophylla', 'Arbusto frondoso con enormes pompones de flores azules o rosas.', 42000, 19, 40, 10, 'https://images.unsplash.com/photo-1508615039623-a25605d2b022?w=500', 'El color de la flor depende del pH del suelo (ácido=azul).', 'Sombra o luz indirecta', 'Frecuente en verano', '80 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (20, 1, 1, 'Helecho de Boston', 'Clásico y frondoso, perfecto para cestas colgantes.', 26000, 19, 60, 15, 'https://images.unsplash.com/photo-1545241047-6083a3684587?w=500', 'Pulverizar agua constantemente, ama la humedad ambiental.', 'Sombra parcial', 'Frecuente', '50 cm', TRUE);
INSERT INTO producto (id_producto, id_categoria, id_tipo, nombre_producto, descripcion, precio, porcentaje_iva, stock, stock_minimo_alerta, imagen_url, cuidados, luz, riego, tamanio_estimado, activo) VALUES (23, 2, 1, 'Azalea Japónica', 'Hermoso arbusto floral para jardines de sombra.', 18000, 19, 815, 20, 'https://images.unsplash.com/photo-1508615039623-a25605d2b022?w=500', 'Suelo ácido y riego con agua sin cal.', 'Semisombra', 'Cada 3 días', '120cm', TRUE);

